/* Independently integrable translation of active SPIR-V1844,1851,1847,1853
 * and recorded Vulkan phases118..133. See REPORT.md for evidence/limits. */
#include "oa_native_bloom.h"
#include <string.h>
extern GLuint oa_post_program(const char *,const char *);
static const char *vertex="#version 300 es\nout vec2 uv;void main(){vec2 p=vec2(float((gl_VertexID<<1)&2),float(gl_VertexID&2));uv=p;gl_Position=vec4(p*2.-1.,0.,1.);}";
static const char *copy_fs="#version 300 es\nprecision highp float;in vec2 uv;uniform sampler2D s;out vec4 o;void main(){o=vec4(texture(s,uv).rgb,0.);}";
static const char *extract_fs="#version 300 es\nprecision highp float;in vec2 uv;uniform sampler2D s;uniform vec3 params;out vec4 o;void main(){vec3 c=texture(s,uv).rgb*params.x;float l=max(dot(c,vec3(.2126,.7152,.0722)),params.y);o=vec4(c*(clamp((l-params.y)*params.z,0.,1.)/l),0.);}";
static const char *blur_fs="#version 300 es\nprecision highp float;in vec2 uv;uniform sampler2D s;uniform vec4 offsets;out vec4 o;void main(){vec4 c=texture(s,uv-offsets.zw)*.390625;c=texture(s,uv-offsets.xy)*.109375+c;c=texture(s,uv+offsets.zw)*.390625+c;o=texture(s,uv+offsets.xy)*.109375+c;}";
static GLuint texture8(int w,int h){GLuint t;glGenTextures(1,&t);glBindTexture(GL_TEXTURE_2D,t);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,0);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);return t;}
static int target(GLuint *f,GLuint t){glGenFramebuffers(1,f);glBindFramebuffer(GL_FRAMEBUFFER,*f);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,t,0);return glCheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE;}
void oa_native_bloom_close(oa_native_bloom *p){glDeleteTextures(7,p->tex);glDeleteFramebuffers(7,p->fbo);if(p->copy)glDeleteProgram(p->copy);if(p->extract)glDeleteProgram(p->extract);if(p->blur)glDeleteProgram(p->blur);memset(p,0,sizeof(*p));}
int oa_native_bloom_open(oa_native_bloom *p,int w,int h){int i;memset(p,0,sizeof(*p));if(w<16||h<16)return 0;for(i=0;i<4;i++){p->w[i]=w>>(i+1);p->h[i]=h>>(i+1);}p->copy=oa_post_program(vertex,copy_fs);p->extract=oa_post_program(vertex,extract_fs);p->blur=oa_post_program(vertex,blur_fs);if(!p->copy||!p->extract||!p->blur)goto fail;for(i=0;i<7;i++){int level=i?((i-1)/2+1):0;p->tex[i]=texture8(p->w[level],p->h[level]);if(!target(&p->fbo[i],p->tex[i]))goto fail;}glBindFramebuffer(GL_FRAMEBUFFER,0);p->ready=glGetError()==GL_NO_ERROR;if(p->ready)return 1;fail:oa_native_bloom_close(p);glBindFramebuffer(GL_FRAMEBUFFER,0);return 0;}
/* Slots:0 half scene;1/2 quarter pingpong;3/4 eighth;5/6 sixteenth. */
static void setup(oa_native_bloom *p,int target_slot,int level,GLuint program,GLuint source){glBindFramebuffer(GL_FRAMEBUFFER,p->fbo[target_slot]);glViewport(0,0,p->w[level],p->h[level]);glUseProgram(program);glActiveTexture(GL_TEXTURE0);glBindTexture(GL_TEXTURE_2D,source);glUniform1i(glGetUniformLocation(program,"s"),0);}
static void draw_copy(oa_native_bloom *p,int target_slot,int level,GLuint source){setup(p,target_slot,level,p->copy,source);glDrawArrays(GL_TRIANGLES,0,3);}
static void pair(oa_native_bloom *p,int slot,int level){float far=2.14285719394683837890625f,near=.60000002384185791015625f;/* measured float offsets: source texels */setup(p,slot+1,level,p->blur,p->tex[slot]);glUniform4f(glGetUniformLocation(p->blur,"offsets"),far/p->w[level],0,near/p->w[level],0);glDrawArrays(GL_TRIANGLES,0,3);setup(p,slot,level,p->blur,p->tex[slot+1]);glUniform4f(glGetUniformLocation(p->blur,"offsets"),0,far/p->h[level],0,near/p->h[level]);glDrawArrays(GL_TRIANGLES,0,3);}
GLuint oa_native_bloom_render(oa_native_bloom *p,GLuint scene,const float params[3]){GLboolean dither=glIsEnabled(GL_DITHER);int i;if(!p->ready||!params||params[1]<=0)return 0;glDisable(GL_DITHER);glDisable(GL_BLEND);/* phase118 */draw_copy(p,0,0,scene);/*119 */setup(p,1,1,p->extract,p->tex[0]);glUniform3fv(glGetUniformLocation(p->extract,"params"),1,params);glDrawArrays(GL_TRIANGLES,0,3);/*120..121 */pair(p,1,1);/*122..124 */draw_copy(p,3,2,p->tex[1]);pair(p,3,2);/*125..131 */draw_copy(p,5,3,p->tex[3]);for(i=0;i<3;i++)pair(p,5,3);/*132..133: LOAD existing blurred level and ADD upsampled lower level. */glEnable(GL_BLEND);glBlendEquation(GL_FUNC_ADD);glBlendFunc(GL_ONE,GL_ONE);draw_copy(p,3,2,p->tex[5]);draw_copy(p,1,1,p->tex[3]);glDisable(GL_BLEND);if(dither)glEnable(GL_DITHER);return p->tex[1];}
